// Cria as 2 paginas novas na "Planilha do Ads ML" (Passo D do procedimento de
// mapeamento SKU x Ads), com header + aviso de validacao.
//
// Segue a condicao do @analyst (11/08/2026): minimizeChrome() e importado do
// modulo unico ja corrigido, nunca reimplementado aqui.
//
// LIMITACAO CONHECIDA E ASSUMIDA: o aviso de validacao e escrito como texto
// simples na linha 1 -- a formatacao "chamativa" (celula mesclada, cor de
// fundo, negrito) descrita na doc NAO e aplicada aqui, porque essa parte
// (cliques em botoes de mesclar/cor) nunca foi testada contra a planilha real
// e eu nao vou inventar esses cliques sem validar antes (BLOCO 0-Z). O texto
// do aviso ja deixa claro que o dado esta em validacao, mesmo sem destaque
// visual.

const { chromium } = require('playwright');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));
const { esperarPlanilhaCarregar, escreverLinha } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/planilha-clipboard.js'));

const SHEET_URL = 'https://docs.google.com/spreadsheets/d/1JI5kUj-F2D946GtH4U3REkryCqpXvacmFlKrn2QFdm8/';
const AVISO = '⚠️ Dados em validação — aguardando confirmação final';

const PAGINAS = [
  {
    nome: 'Prioridade - Fora de Ads',
    colunas: ['SKU', 'MLB(s)', 'Título de catálogo', 'Depósito (un)', 'FULL (un)'],
  },
  {
    nome: 'Mapeamento Completo da Planilha',
    colunas: ['SKU', 'MLB(s) conhecidos', 'Título de catálogo', 'Status (Ativo/Pausado/Sem estoque)', 'Status em Ads (Ativa/Pausada/Sem Campanha)'],
  },
];

async function criarPagina(page, nome) {
  await page.locator('button[aria-label="Adicionar página"]').click();
  await page.waitForTimeout(800);

  // A aba recem-criada e sempre a ultima da lista, com nome generico ("PáginaN")
  const abas = page.locator('.docs-sheet-tab-name');
  const novaAba = abas.last();
  await novaAba.dblclick();
  await page.waitForTimeout(300);
  await page.keyboard.press('Control+a');
  await page.keyboard.type(nome, { delay: 30 });
  await page.keyboard.press('Enter');
  await page.waitForTimeout(500);
}

async function irParaAba(page, nome) {
  await page.locator('.docs-sheet-tab-name', { hasText: nome }).first().click();
  await page.waitForTimeout(500);
  await esperarPlanilhaCarregar(page);
}

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    const page = await openBackgroundPage(browser, context, SHEET_URL);
    await page.waitForLoadState('domcontentloaded', { timeout: 30000 });
    await esperarPlanilhaCarregar(page);

    const abasAntes = await page.locator('.docs-sheet-tab-name').allTextContents();
    console.log('ABAS_ANTES:', JSON.stringify(abasAntes));

    if (abasAntes.length !== 2) {
      throw new Error(`Esperava exatamente 2 abas existentes antes de criar as novas, achei ${abasAntes.length}: ${JSON.stringify(abasAntes)} -- parando por segurança.`);
    }

    for (const pagina of PAGINAS) {
      console.log(`Criando pagina "${pagina.nome}"...`);
      await criarPagina(page, pagina.nome);

      console.log(`Indo pra pagina "${pagina.nome}" pra escrever header + aviso...`);
      await irParaAba(page, pagina.nome);

      await escreverLinha(page, 'A1', [AVISO]);
      await escreverLinha(page, 'A2', pagina.colunas);
      console.log(`Header + aviso escritos em "${pagina.nome}".`);
    }

    const abasDepois = await page.locator('.docs-sheet-tab-name').allTextContents();
    console.log('ABAS_DEPOIS:', JSON.stringify(abasDepois));

    const abasOriginaisIntactas = abasAntes.every((a) => abasDepois.includes(a));
    console.log('ABAS_ORIGINAIS_INTACTAS:', abasOriginaisIntactas);

    console.log('OK_CONCLUIDO');
  } catch (err) {
    console.error('ERRO:', err.message);
    process.exitCode = 1;
  } finally {
    if (browser) {
      await minimizeChrome();
      await browser.close();
    }
  }
})();

