const { chromium } = require('playwright');

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    const pages = context.pages();
    console.log('ABAS_ABERTAS:', pages.map((p) => p.url()));

    const sheetPage = pages.find((p) => p.url().includes('docs.google.com/spreadsheets'));
    if (!sheetPage) {
      console.log('NENHUMA_ABA_DA_PLANILHA_ENCONTRADA');
      return;
    }

    // Procura por qualquer botao cujo aria-label contenha "gina" (pagina/página, evita problema de acento)
