const { chromium } = require('playwright');
(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    const pages = context.pages();
    for (const p of pages) {
      const url = p.url();
      if (url.includes('mercadolivre.com.br/anuncios') || url === 'chrome://new-tab-page/') {
        console.log(`Fechando: ${url}`);
        await p.close().catch(() => {});
      } else if (url.includes('docs.google.com/spreadsheets')) {
        console.log(`Mantendo (planilha): ${url}`);
      }
    }
    // Se sobrou mais de 1 aba da planilha, fecha as extras (mantem so a primeira)
    const sheetPages = context.pages().filter((p) => p.url().includes('docs.google.com/spreadsheets'));
    for (let i = 1; i < sheetPages.length; i++) {
      console.log(`Fechando aba duplicada de planilha: ${sheetPages[i].url()}`);
      await sheetPages[i].close().catch(() => {});
    }
    console.log('--- Abas restantes ---');
    for (const p of context.pages()) console.log(p.url());
  } catch (err) {
    console.error('ERRO:', err.message);
  } finally {
    if (browser) await browser.close();
  }
  process.exit(0);
})();

