const { chromium } = require('playwright');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

const SKU = 'HQ-HQMGI45-220V';
const TITULO_ESPERADO = 'Máquina De Gelo Profissional Hq 45kg Turbo Hq-hqmgi45';
const URL_ANUNCIOS = 'https://vendedores.mercadolivre.com.br/anuncios#menu-user';

function extrairMlbsDoProduto(blocoTexto, tituloEsperado) {
  const linhas = blocoTexto.split('\n').map((l) => l.trim()).filter((l) => l.length > 0);
  const pares = [];
  for (let i = 0; i < linhas.length; i++) {
    if (/^#\d{7,11}(\s*\|\s*#\d{7,11})*$/.test(linhas[i]) && i > 0) {
      pares.push({ titulo: linhas[i - 1], mlbLinha: linhas[i] });
    }
  }
  const encontrados = pares.filter((p) => p.titulo.toLowerCase().includes(tituloEsperado.toLowerCase()));
  const mlbs = new Set();
  encontrados.forEach((p) => {
    (p.mlbLinha.match(/#\d{7,11}/g) || []).forEach((m) => mlbs.add(m));
  });
  return { pares, mlbs: [...mlbs] };
}

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    const pages = context.pages();
    const page = pages.find((p) => p.url().includes('vendedores.mercadolivre.com.br/anuncios'))
      || await openBackgroundPage(browser, context, URL_ANUNCIOS);
    await page.waitForTimeout(500);

    const campoBusca = page.locator('input[placeholder*="Buscar" i]').first();
    await campoBusca.click();
    await campoBusca.fill('');
    await campoBusca.fill(SKU);
    await page.keyboard.press('Enter');
    await page.waitForTimeout(3000);

    const texto = await page.locator('body').innerText();
    const inicio = texto.indexOf('Seus anúncios');
    const fim = texto.indexOf('Suas vendas');
    const bloco = texto.slice(inicio, fim);
    console.log('--- Bloco de resultado (busca por SKU) ---');
    console.log(bloco);

    const { pares, mlbs } = extrairMlbsDoProduto(bloco, TITULO_ESPERADO);
    console.log('TODOS_OS_PARES_TITULO_MLB_ACHADOS:', JSON.stringify(pares, null, 2));
    console.log('MLBs_DO_PRODUTO_CERTO (filtrado por titulo):', JSON.stringify(mlbs));
  } catch (err) {
    console.error('ERRO:', err.message);
  } finally {
    if (browser) {
      await minimizeChrome();
      await browser.close();
    }
  }
  process.exit(0);
})();

