const { chromium } = require('playwright');
const path = require('path');
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    const page = context.pages().find((p) => p.url().includes('vendedores.mercadolivre.com.br'));
    if (!page) throw new Error('Nenhuma aba de vendedores.mercadolivre.com.br aberta');

    console.log('URL atual:', page.url());
    console.log('Titulo:', await page.title());

    // Lista todos os elementos de menu/link visiveis que contenham "anúncio" ou "gestão" (case insensitive)
    const itens = await page.evaluate(() => {
      const els = Array.from(document.querySelectorAll('a, [role="link"], [role="button"], li, span, div'));
      const vistos = new Set();
      const resultado = [];
      for (const el of els) {
        const txt = (el.textContent || '').trim();
        if (txt.length > 0 && txt.length < 60 && /anúncio|gestão/i.test(txt) && el.children.length <= 1) {
          const key = txt + '|' + el.tagName;
          if (!vistos.has(key)) {
            vistos.add(key);
            resultado.push({ tag: el.tagName, texto: txt, visivel: el.offsetParent !== null, className: (el.className || '').toString().slice(0, 80) });
          }
        }
      }
      return resultado;
    });
    console.log('ITENS_DE_MENU_ENCONTRADOS:', JSON.stringify(itens, null, 2));
  } catch (err) {
    console.error('ERRO:', err.message);
  } finally {
    if (browser) {
      await minimizeChrome();
      await browser.close();
    }
  }
  process.exit(0);
})();

