$wb = $excel.Workbooks | Where-Object { $_.Name -eq 'ANÚNCIOS EM POTENCIAL - KARZEN ELETRO (1) (1).xlsx' }
Write-Output "---"
Write-Output "Selecionado: $($wb.Name)"
$wb.Worksheets | ForEach-Object { Write-Output " - $($_.Name)" }

function Get-CorPorSku {
    param([string]$Sku)
    $hash = 0
    foreach ($c in $Sku.ToCharArray()) { $hash = ($hash * 31 + [int][char]$c) -band 0xFFFFFFF }
    $hue = $hash % 360
    # HSL fixo: saturacao 65%, luminosidade 75% (cor clara, boa pra fundo de celula, texto preto continua legivel)
    $s = 0.65; $l = 0.75
    $c = (1 - [Math]::Abs(2*$l - 1)) * $s
    $x = $c * (1 - [Math]::Abs((($hue/60) % 2) - 1))
    $m = $l - $c/2
    if ($hue -lt 60) { $r=$c;$g=$x;$b=0 }
    elseif ($hue -lt 120) { $r=$x;$g=$c;$b=0 }
    elseif ($hue -lt 180) { $r=0;$g=$c;$b=$x }
    elseif ($hue -lt 240) { $r=0;$g=$x;$b=$c }
    elseif ($hue -lt 300) { $r=$x;$g=0;$b=$c }
    else { $r=$c;$g=0;$b=$x }
    $R = [Math]::Round(($r+$m)*255)
    $G = [Math]::Round(($g+$m)*255)
    $B = [Math]::Round(($b+$m)*255)
    Write-Output "RGB($R,$G,$B)"
    return ($B*65536 + $G*256 + $R)
}

