// Passo B -- confirmar status em Ads, pagina "Anuncios Patrocinados".
const { chromium } = require('playwright');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

const URL_ADS = 'https://ads.mercadolivre.com.br/product-ads/admin/ads?navigate_to=mercado_ads';
const MLB_TESTE = 'MLB4734682211'; // um dos 4 MLBs da linha 2

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    let page = context.pages().find((p) => p.url().includes('ads.mercadolivre.com.br'));
    if (!page) page = await openBackgroundPage(browser, context, URL_ADS);
    await page.waitForLoadState('load', { timeout: 30000 }).catch(() => {});
    await page.waitForTimeout(3000);
    console.log('URL:', page.url());

    // Fecha qualquer drawer de variacoes que tenha sobrado, conforme doc
    const fecharDrawer = page.locator('button[aria-label="Cerrar"]');
    if (await fecharDrawer.count() > 0) {
      console.log('Fechando drawer de variacoes residual...');
      await fecharDrawer.first().click().catch(() => {});
      await page.waitForTimeout(500);
    }

    const inputs = await page.evaluate(() =>
      Array.from(document.querySelectorAll('input')).map((i, idx) => ({
        idx, type: i.type, placeholder: i.placeholder, visible: i.offsetParent !== null,
      }))
    );
    console.log('INPUTS_NA_PAGINA:', JSON.stringify(inputs));

    const campoBusca = page.locator('input[placeholder="Procurar por # ou título"]').first();
    await campoBusca.click({ timeout: 8000 });
    await campoBusca.fill(MLB_TESTE);
    await page.keyboard.press('Enter');
    await page.waitForTimeout(3000);

    const texto = await page.locator('body').innerText();
    for (const termo of ['Ativa', 'Ativo', 'Pausada', 'Pausado', 'Sem campanha', 'ativa', 'pausada']) {
      const i = texto.indexOf(termo);
      if (i !== -1) {
        console.log(`--- Achou "${termo}" na posição ${i} ---`);
        console.log(texto.slice(Math.max(0, i - 200), i + 100));
        console.log('===');
      }
    }

    // Tambem tenta achar via elementos com classe/aria relacionados a status (badge/pill)
    const badges = await page.evaluate(() => {
      const els = Array.from(document.querySelectorAll('[class*="status" i], [class*="pill" i], [class*="badge" i], [class*="tag" i]'));
      return els.filter(el => el.offsetParent !== null).map(el => ({ texto: el.textContent.trim().slice(0,60), className: el.className.toString().slice(0,80) })).filter(e => e.texto.length > 0 && e.texto.length < 40);
    });
    console.log('BADGES_DE_STATUS_NA_PAGINA:', JSON.stringify(badges, null, 2));
  } catch (err) {
    console.error('ERRO:', err.message);
  } finally {
    if (browser) {
      await minimizeChrome();
      await browser.close();
    }
  }
  process.exit(0);
})();

