// Passo A validado, linha 3 (Item ID 4594566887, Tanquinho Lcs15).
const { chromium } = require('playwright');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

const URL_ANUNCIOS = 'https://vendedores.mercadolivre.com.br/anuncios#menu-user';
const ITEM_ID = '4594566887'; // linha 3
const SELETOR_BUSCA_CERTO = 'input[placeholder="Buscar por título, código ou SKU"]';

function extrairCardsComSku(textoBloco) {
  const linhas = textoBloco.split('\n').map((l) => l.trim()).filter((l) => l.length > 0);
  const cards = [];
  let mlbsAcumulados = [];
  for (const linha of linhas) {
    if (/^#\d{7,11}$/.test(linha)) {
      mlbsAcumulados.push(linha);
    } else if (/^SKU\s+/i.test(linha)) {
      const skuValor = linha.replace(/^SKU\s+/i, '').trim();
      if (mlbsAcumulados.length > 0) {
        cards.push({ mlbs: [...mlbsAcumulados], sku: skuValor });
        mlbsAcumulados = [];
      }
    }
  }
  return cards;
}

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    let page = context.pages().find((p) => p.url().includes('vendedores.mercadolivre.com.br/anuncios'));
    if (!page) page = await openBackgroundPage(browser, context, URL_ANUNCIOS);
    await page.waitForTimeout(1500);

    // 1a busca: pelo Item ID puro
    const campo = page.locator(SELETOR_BUSCA_CERTO).first();
    await campo.click();
    await campo.fill('');
    await campo.fill(ITEM_ID);
    await page.keyboard.press('Enter');
    await page.waitForTimeout(3000);

    let texto = await page.locator('body').innerText();
    let idxFiltrar = texto.indexOf('Filtrar e ordenar');
    let idxRodape = texto.indexOf('Você recebeu');
    let bloco = texto.slice(idxFiltrar, idxRodape !== -1 ? idxRodape : idxFiltrar + 2000);
    console.log('--- Resultado da 1a busca (Item ID) ---');
    console.log(bloco);

    const primeiroCard = extrairCardsComSku(bloco);
    if (primeiroCard.length === 0) {
      console.log('NENHUM_RESULTADO -- anuncio pode nao existir mais');
      return;
    }
    const sku = primeiroCard[0].sku;
    console.log('SKU_ENCONTRADO:', sku);

    // 2a busca: pelo SKU
    await campo.click();
    await campo.fill('');
    await campo.fill(sku);
    await page.keyboard.press('Enter');
    await page.waitForTimeout(3000);

    texto = await page.locator('body').innerText();
    idxFiltrar = texto.indexOf('Filtrar e ordenar');
    idxRodape = texto.indexOf('Você recebeu');
    bloco = texto.slice(idxFiltrar, idxRodape !== -1 ? idxRodape : idxFiltrar + 3000);
    console.log('--- Resultado da 2a busca (SKU) ---');
    console.log(bloco);

    const cards = extrairCardsComSku(bloco);
    console.log('CARDS_EXTRAIDOS:', JSON.stringify(cards, null, 2));
    const todosBatem = cards.every((c) => c.sku === sku);
    const mlbsFinais = cards.filter((c) => c.sku === sku).flatMap((c) => c.mlbs);
    console.log(`TODOS_OS_CARDS_TEM_O_SKU_CERTO (${sku}):`, todosBatem);
    console.log('MLBs_FINAIS_CONFIRMADOS:', JSON.stringify(mlbsFinais));
  } catch (err) {
    console.error('ERRO:', err.message);
  } finally {
    if (browser) {
      await minimizeChrome();
      await browser.close();
    }
  }
  process.exit(0);
})();

