// Processa um lote de linhas: Passo A (SKU + MLBs confirmados) + Passo B (status em Ads).
// Nao mexe no Excel -- so gera um JSON com os resultados, pra depois o Passo C (PowerShell/COM) ler.
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

const URL_ANUNCIOS = 'https://vendedores.mercadolivre.com.br/anuncios#menu-user';
const URL_ADS = 'https://ads.mercadolivre.com.br/product-ads/admin/ads?navigate_to=mercado_ads';
const SELETOR_BUSCA_ANUNCIOS = 'input[placeholder="Buscar por título, código ou SKU"]';
const SELETOR_BUSCA_ADS = 'input[placeholder="Procurar por # ou título"]';

// Lote atual: linhas 5-24
const LOTE = [
  { row: 5, itemId: '4734808493' },
  { row: 6, itemId: '6716539200' },
  { row: 7, itemId: '4562032101' },
  { row: 8, itemId: '6588111386' },
  { row: 9, itemId: '6844226556' },
  { row: 10, itemId: '4734441301' },
  { row: 11, itemId: '4719874527' },
  { row: 12, itemId: '5770021990' },
  { row: 13, itemId: '6712897810' },
  { row: 14, itemId: '3958548259' },
  { row: 15, itemId: '4560946507' },
  { row: 16, itemId: '4561510195' },
  { row: 17, itemId: '4683210039' },
  { row: 18, itemId: '4367394365' },
  { row: 19, itemId: '4519135747' },
  { row: 20, itemId: '6520622460' },
  { row: 21, itemId: '5267746586' },
  { row: 22, itemId: '4366395951' },
  { row: 23, itemId: '4632339143' },
  { row: 24, itemId: '3566777787' },
];

function extrairCardsComSku(textoBloco) {
  const linhas = textoBloco.split('\n').map((l) => l.trim()).filter((l) => l.length > 0);
  const cards = [];
  let mlbsAcumulados = [];
  for (const linha of linhas) {
    if (/^#\d{7,11}$/.test(linha)) {
      mlbsAcumulados.push(linha);
    } else if (/^SKU\s+/i.test(linha)) {
      const skuValor = linha.replace(/^SKU\s+/i, '').trim();
      if (mlbsAcumulados.length > 0) {
        cards.push({ mlbs: [...mlbsAcumulados], sku: skuValor });
        mlbsAcumulados = [];
      }
    }
  }
  return cards;
}

async function buscarNaPaginaAnuncios(page, termo) {
  const campo = page.locator(SELETOR_BUSCA_ANUNCIOS).first();
  await campo.click();
  await campo.fill('');
  await campo.fill(termo);
  await page.keyboard.press('Enter');
  await page.waitForTimeout(2800);
  const texto = await page.locator('body').innerText();
  const idxFiltrar = texto.indexOf('Filtrar e ordenar');
  const idxRodape = texto.indexOf('Você recebeu');
  return texto.slice(idxFiltrar, idxRodape !== -1 ? idxRodape : idxFiltrar + 4000);
}

async function processarPassoA(page, itemId) {
  const bloco1 = await buscarNaPaginaAnuncios(page, itemId);
  const cards1 = extrairCardsComSku(bloco1);
  if (cards1.length === 0) {
    return { erro: 'ANUNCIO_NAO_ENCONTRADO' };
  }
  const sku = cards1[0].sku;

  const bloco2 = await buscarNaPaginaAnuncios(page, sku);
  const cards2 = extrairCardsComSku(bloco2);
  const todosBatem = cards2.every((c) => c.sku === sku);
  const mlbs = cards2.filter((c) => c.sku === sku).flatMap((c) => c.mlbs);

  if (!todosBatem) {
    return { erro: 'CARD_COM_SKU_DIFERENTE_NA_BUSCA', sku, cardsEncontrados: cards2 };
  }
  if (mlbs.length === 0) {
    return { erro: 'NENHUM_MLB_CONFIRMADO', sku };
  }
  return { sku, mlbs: mlbs.map((m) => m.replace('#', '')) };
}

async function processarPassoB(page, mlb) {
  const fecharDrawer = page.locator('button[aria-label="Cerrar"]');
  if (await fecharDrawer.count() > 0) {
    await fecharDrawer.first().click().catch(() => {});
    await page.waitForTimeout(400);
  }
  const campo = page.locator(SELETOR_BUSCA_ADS).first();
  await campo.click();
  await campo.fill('');
  await campo.fill(`MLB${mlb}`);
  await page.keyboard.press('Enter');
  await page.waitForTimeout(2800);

  const texto = await page.locator('body').innerText();
  const idxCatalogo = texto.indexOf('CATÁLOGO');
  if (idxCatalogo === -1) {
    return { erro: 'RESULTADO_ADS_NAO_ENCONTRADO' };
  }
  const bloco = texto.slice(idxCatalogo, idxCatalogo + 500);
  const semCampanha = bloco.includes('Sem Campanha');
  if (semCampanha) return { status: 'Sem Campanha' };

  const temPausado = await page.evaluate(() => {
    const els = Array.from(document.querySelectorAll('*'));
    return els.some((el) => el.children.length === 0 && el.textContent.trim() === 'PAUSADO' && el.offsetParent !== null);
  });
  return { status: temPausado ? 'Pausada' : 'Ativa' };
}

(async () => {
  let browser;
  const resultados = [];
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];

    let pageAnuncios = context.pages().find((p) => p.url().includes('vendedores.mercadolivre.com.br/anuncios'));
    if (!pageAnuncios) pageAnuncios = await openBackgroundPage(browser, context, URL_ANUNCIOS);
    await pageAnuncios.waitForTimeout(1000);

    let pageAds = context.pages().find((p) => p.url().includes('ads.mercadolivre.com.br'));
    if (!pageAds) pageAds = await openBackgroundPage(browser, context, URL_ADS);
    await pageAds.waitForTimeout(1000);

    for (const item of LOTE) {
      console.log(`Processando linha ${item.row} (Item ID ${item.itemId})...`);
      try {
        const passoA = await processarPassoA(pageAnuncios, item.itemId);
        if (passoA.erro) {
          console.log(`  Passo A falhou: ${passoA.erro}`);
          resultados.push({ row: item.row, itemId: item.itemId, ...passoA });
          continue;
        }
        console.log(`  SKU: ${passoA.sku} | MLBs: ${passoA.mlbs.join(', ')}`);

        const passoB = await processarPassoB(pageAds, passoA.mlbs[0]);
        if (passoB.erro) {
          console.log(`  Passo B falhou: ${passoB.erro}`);
          resultados.push({ row: item.row, itemId: item.itemId, sku: passoA.sku, mlbs: passoA.mlbs, statusErro: passoB.erro });
          continue;
        }
        console.log(`  Status em Ads: ${passoB.status}`);

        resultados.push({ row: item.row, itemId: item.itemId, sku: passoA.sku, mlbs: passoA.mlbs, status: passoB.status });
      } catch (err) {
        console.log(`  ERRO INESPERADO na linha ${item.row}: ${err.message}`);
        resultados.push({ row: item.row, itemId: item.itemId, erro: `EXCECAO: ${err.message}` });
      }
    }

    const caminhoSaida = path.resolve(__dirname, 'lote-05-24.json');
    fs.writeFileSync(caminhoSaida, JSON.stringify(resultados, null, 2));
    console.log(`\nResultado salvo em: ${caminhoSaida}`);
  } catch (err) {
    console.error('ERRO GERAL:', err.message);
  } finally {
    if (browser) {
      await minimizeChrome();
      await browser.close();
    }
  }
  process.exit(0);
})();

