// Testa a captura do rotulo Classico/Premium associado a cada MLB, na linha 4
// (ja validada antes: card1 #4722742973=Classico #4722782047=Premium;
//  card2 #4722755255=Classico #4722782041=Premium -- confirmar contra isso).
const { chromium } = require('playwright');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

const URL_ANUNCIOS = 'https://vendedores.mercadolivre.com.br/anuncios#menu-user';
const SKU = 'HQ-100CFX-127V';
const SELETOR_BUSCA = 'input[placeholder="Buscar por título, código ou SKU"]';

function extrairCardsComRotulos(textoBloco) {
  const linhas = textoBloco.split('\n').map((l) => l.trim());
  const cards = [];
  let atual = null;
  for (let i = 0; i < linhas.length; i++) {
    const linha = linhas[i];
    if (/^#\d{7,11}(\s*\|\s*#\d{7,11})*$/.test(linha) && linhas[i+1] && /^SKU\s+/i.test(linhas[i+1])) {
      // nova secao de card: as linhas de MLB vem ANTES do SKU, entao precisamos olhar pra tras
      // procura pra tras ate achar o titulo (linha nao vazia antes do primeiro #)
      let j = i;
      const mlbs = [];
      while (j >= 0 && /^#\d{7,11}$/.test(linhas[j])) { mlbs.unshift(linhas[j]); j--; }
      const sku = linhas[i+1].replace(/^SKU\s+/i, '').trim();
      atual = { mlbs, sku, opcoes: [] };
      cards.push(atual);
    }
    if (atual && /^(Clássico|Premium)$/i.test(linha)) {
      atual.opcoes.push(linha);
    }
  }
  return cards;
}

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    let page = context.pages().find((p) => p.url().includes('vendedores.mercadolivre.com.br/anuncios'));
    if (!page) page = await openBackgroundPage(browser, context, URL_ANUNCIOS);
    await page.waitForTimeout(1000);

    const campo = page.locator(SELETOR_BUSCA).first();
    await campo.click();
    await campo.fill('');
    await campo.fill(SKU);
    await page.keyboard.press('Enter');
    await page.waitForTimeout(3000);

    const texto = await page.locator('body').innerText();
    const idxFiltrar = texto.indexOf('Filtrar e ordenar');
    const idxRodape = texto.indexOf('Você recebeu');
    const bloco = texto.slice(idxFiltrar, idxRodape !== -1 ? idxRodape : idxFiltrar + 4000);

    const cards = extrairCardsComRotulos(bloco);
    console.log('CARDS_COM_ROTULOS:', JSON.stringify(cards, null, 2));
  } catch (err) {
    console.error('ERRO:', err.message);
  } finally {
    if (browser) {
      await minimizeChrome();
      await browser.close();
    }
  }
  process.exit(0);
})();

