// Recaptura, pra cada SKU ja confirmado no lote 5-24, o agrupamento Classico/Premium
// dos MLBs -- validado contra a linha 4 (bate 100%) e linha 5 (Felipe confirmou que
// a extracao automatica esta certa).
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

const URL_ANUNCIOS = 'https://vendedores.mercadolivre.com.br/anuncios#menu-user';
const SELETOR_BUSCA = 'input[placeholder="Buscar por título, código ou SKU"]';

function extrairCardsComRotulos(textoBloco) {
  const linhas = textoBloco.split('\n').map((l) => l.trim());
  const cards = [];
  for (let i = 0; i < linhas.length; i++) {
    const linha = linhas[i];
    if (/^#\d{7,11}(\s*\|\s*#\d{7,11})*$/.test(linha) && linhas[i+1] && /^SKU\s+/i.test(linhas[i+1])) {
      let j = i;
      const mlbs = [];
      while (j >= 0 && /^#\d{7,11}$/.test(linhas[j])) { mlbs.unshift(linhas[j].replace('#','')); j--; }
      const sku = linhas[i+1].replace(/^SKU\s+/i, '').trim();
      const opcoes = [];
      for (let k = i + 2; k < linhas.length && opcoes.length < mlbs.length; k++) {
        if (/^(Clássico|Premium)$/i.test(linhas[k])) opcoes.push(linhas[k]);
        if (/^#\d{7,11}/.test(linhas[k]) && k > i + 2) break; // proximo card comecando
      }
      cards.push({ mlbs, sku, opcoes });
    }
  }
  return cards;
}

function agruparPorRotulo(cards, skuAlvo) {
  const grupos = {};
  for (const card of cards) {
    if (card.sku !== skuAlvo) continue;
    card.mlbs.forEach((mlb, idx) => {
      const rotulo = card.opcoes[idx] || 'SemRotulo';
      if (!grupos[rotulo]) grupos[rotulo] = [];
      grupos[rotulo].push(mlb);
    });
  }
  return grupos;
}

(async () => {
  let browser;
  const dadosLote = JSON.parse(fs.readFileSync(path.resolve(__dirname, 'lote-05-24.json'), 'utf8'));
  const skusUnicos = [...new Map(dadosLote.filter((d) => d.sku).map((d) => [d.sku, d])).values()];

  const resultado = {};
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    let page = context.pages().find((p) => p.url().includes('vendedores.mercadolivre.com.br/anuncios'));
    if (!page) page = await openBackgroundPage(browser, context, URL_ANUNCIOS);
    await page.waitForTimeout(1000);

    for (const item of skusUnicos) {
      console.log(`Buscando SKU ${item.sku}...`);
      const campo = page.locator(SELETOR_BUSCA).first();
      await campo.click();
      await campo.fill('');
      await campo.fill(item.sku);
      await page.keyboard.press('Enter');
