// Abrir link em nova guia), checar "COMPETINDO" + status Ativa/Inativa em "Concorrencia no
// Mercado Livre", fechar a aba depois. Objetivo: achar o 1o MLB Classico e o 1o MLB Premium
// validos (catalogo + Ativa).
const { chromium } = require('playwright');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

const URL_ANUNCIOS = 'https://vendedores.mercadolivre.com.br/anuncios#menu-user';
const SELETOR_BUSCA = 'input[placeholder="Buscar por título, código ou SKU"]';
const SKU = 'TVSAM-43';

async function checarCatalogo(context, mlb, pageAnuncios) {
  // Acha o link "Ver anúncio"/menu de 3 pontinhos do card desse MLB e abre "Alterar" numa aba nova
  // Estrategia: procurar o texto do MLB na pagina, achar o container do card, abrir o menu de 3 pontinhos
  const cardMlb = pageAnuncios.locator(`text=#${mlb}`).first();
  const menuBtn = cardMlb.locator('xpath=ancestor::*[position()<=6]//button[contains(@aria-label,"más") or contains(@aria-label,"Más") or contains(@aria-label,"menu" ) or contains(@aria-label,"opç")]').first();

  // fallback: procurar qualquer botao de 3 pontinhos (icon-button) perto do card
  let contexto = cardMlb.locator('xpath=ancestor::*[self::tr or contains(@class,"row") or contains(@class,"card")][1]');
  if (await contexto.count() === 0) contexto = cardMlb;

  const botao3pontos = contexto.locator('button').filter({ has: pageAnuncios.locator('svg') }).last();

  console.log(`  Tentando achar menu de 3 pontinhos pro MLB ${mlb}...`);
  const totalBotoes = await contexto.locator('button').count();
  console.log(`  Botoes encontrados no contexto do card: ${totalBotoes}`);

  return null; // exploratorio por enquanto
}

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    let page = context.pages().find((p) => p.url().includes('vendedores.mercadolivre.com.br/anuncios'));
    if (!page) page = await openBackgroundPage(browser, context, URL_ANUNCIOS);
    await page.waitForTimeout(1000);

    const campo = page.locator(SELETOR_BUSCA).first();
    await campo.click();
    await campo.fill('');
    await campo.fill(SKU);
    await page.keyboard.press('Enter');
    await page.waitForTimeout(3000);

    // Primeiro: so mapear a estrutura HTML ao redor de um MLB pra entender onde fica o menu de 3 pontinhos
    const estrutura = await page.evaluate((mlbAlvo) => {
      const els = Array.from(document.querySelectorAll('*'));
      const alvo = els.find(el => el.children.length === 0 && el.textContent.trim() === `#${mlbAlvo}`);
      if (!alvo) return { erro: 'nao achou o elemento do MLB' };
      let atual = alvo;
      const caminho = [];
      for (let i = 0; i < 8 && atual; i++) {
        const botoes = Array.from(atual.querySelectorAll('button')).map(b => ({
          ariaLabel: b.getAttribute('aria-label'),
          texto: b.textContent.trim().slice(0,30),
        }));
        caminho.push({ tag: atual.tagName, className: (atual.className||'').toString().slice(0,60), botoes });
        atual = atual.parentElement;
      }
      return { caminho };
    }, '4484796429');
    console.log(JSON.stringify(estrutura, null, 2));
  } catch (err) {
    console.error('ERRO:', err.message);
  } finally {
    if (browser) {
      await minimizeChrome();
      await browser.close();
    }
  }
  process.exit(0);
})();

