const { chromium } = require('playwright');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

const URL_ANUNCIOS = 'https://vendedores.mercadolivre.com.br/anuncios#menu-user';
const SELETOR_BUSCA = 'input[placeholder="Buscar por título, código ou SKU"]';
const SKU = 'TVSAM-43';

const CANDIDATOS = {
  Premium: ['4484796429', '4786797457', '4484718899', '4484758197'],
  'Clássico': ['6712897822', '6733267870', '6712897810'],
};

async function abrirAlterarDoMlb(page, context, mlb) {
  const elMlb = page.locator(`text=#${mlb}`).first();
  const linhaCard = elMlb.locator('xpath=ancestor::div[contains(@class,"sll-list-grid-row__main-row")]').first();
  const botao3pontos = linhaCard.locator('button[aria-label="Ações secundárias"]').first();
  await botao3pontos.click();
  await page.waitForTimeout(500);
  const linkAlterar = page.locator('a', { hasText: 'Alterar' }).first();
  const href = await linkAlterar.getAttribute('href');
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  if (!href) return null;
  const urlCompleta = href.startsWith('http') ? href : `https://vendedores.mercadolivre.com.br${href}`;
  const pageAlterar = await openBackgroundPage(context.browser(), context, urlCompleta);
  await pageAlterar.waitForLoadState('load', { timeout: 20000 }).catch(() => {});
  await pageAlterar.waitForTimeout(2200);
  return pageAlterar;
}

function extrairStatusConcorrencia(texto) {
  const idx = texto.indexOf('Concorrência no Mercado Livre');
  if (idx === -1) return { temSecao: false };
  const bloco = texto.slice(idx, idx + 500);
  const temCompetindo = texto.slice(Math.max(0, idx - 800), idx).includes('COMPETINDO');
  const ativa = /\bAtiva\b/.test(bloco) && !/Todas as opções.*inativas/i.test(bloco);
  const linhas = bloco.split('\n').map(l => l.trim()).filter(Boolean);
  const idxStatusLinha = linhas.findIndex(l => l === 'Ativa' || l === 'Inativa');
  const status = idxStatusLinha !== -1 ? linhas[idxStatusLinha] : (ativa ? 'Ativa' : 'Inativa/Indeterminado');
  return { temSecao: true, temCompetindo, status };
}

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    let page = context.pages().find((p) => p.url().includes('vendedores.mercadolivre.com.br/anuncios'));
    if (!page) page = await openBackgroundPage(browser, context, URL_ANUNCIOS);
    await page.waitForTimeout(1000);

    const campo = page.locator(SELETOR_BUSCA).first();
    await campo.click();
    await campo.fill('');
    await campo.fill(SKU);
    await page.keyboard.press('Enter');
    await page.waitForTimeout(3000);

    const resultado = {};
    for (const [rotulo, mlbs] of Object.entries(CANDIDATOS)) {
      console.log(`--- Categoria: ${rotulo} ---`);
      let achado = null;
      for (const mlb of mlbs) {
        console.log(`Checando MLB ${mlb}...`);
        const pageAlterar = await abrirAlterarDoMlb(page, context, mlb);
        if (!pageAlterar) { console.log('  Falhou ao abrir Alterar'); continue; }
        const texto = await pageAlterar.locator('body').innerText();
        const info = extrairStatusConcorrencia(texto);
        console.log(`  Resultado: ${JSON.stringify(info)}`);
        await pageAlterar.close();

        if (info.temSecao && info.temCompetindo && info.status === 'Ativa') {
          achado = mlb;
          console.log(`  >>> MLB ${mlb} e o primeiro valido pra ${rotulo}!`);
          break;
        }
      }
      resultado[rotulo] = achado;
    }

    console.log('\nRESULTADO_FINAL:', JSON.stringify(resultado, null, 2));
  } catch (err) {
    console.error('ERRO:', err.message);
  } finally {
    if (browser) {
      await minimizeChrome();
      await browser.close();
    }
  }
  process.exit(0);
})();

