const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));
const { extrairOpcoesDeCatalogo } = require('./extrator-catalogo-v2.js');

const URL_ANUNCIOS = 'https://vendedores.mercadolivre.com.br/anuncios#menu-user';
const SELETOR_BUSCA = 'input[placeholder="Buscar por título, código ou SKU"]';

(async () => {
  let browser;
  const dadosLote = JSON.parse(fs.readFileSync(path.resolve(__dirname, 'lote-05-24.json'), 'utf8'));
  const skusUnicos = [...new Map(dadosLote.filter((d) => d.sku).map((d) => [d.sku, d])).values()];
  const resultado = {};

  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    let page = context.pages().find((p) => p.url().includes('vendedores.mercadolivre.com.br/anuncios'));
    if (!page) page = await openBackgroundPage(browser, context, URL_ANUNCIOS);
    await page.waitForTimeout(1000);

    for (const item of skusUnicos) {
      console.log(`\n=== SKU: ${item.sku} ===`);
      const campo = page.locator(SELETOR_BUSCA).first();
      await campo.click();
      await campo.fill('');
      await campo.fill(item.sku);
      await page.keyboard.press('Enter');
      await page.waitForTimeout(2800);

      const texto = await page.locator('body').innerText();
      const idxFiltrar = texto.indexOf('Filtrar e ordenar');
      const idxRodape = texto.indexOf('Você recebeu');
      const bloco = texto.slice(idxFiltrar, idxRodape !== -1 ? idxRodape : idxFiltrar + 6000);

      const opcoes = extrairOpcoesDeCatalogo(bloco, item.sku);
      console.log(`  Opções encontradas: ${JSON.stringify(opcoes)}`);

      const achado = { 'Clássico': null, 'Premium': null };
      for (const op of opcoes) {
        if (op.status && ['GANHANDO','PERDENDO','COMPARTILHANDO'].includes(op.status) && !achado[op.condicao]) {
          achado[op.condicao] = { mlb: op.mlb, status: op.status };
        }
      }
      const precisaAlterar = { 'Clássico': !achado['Clássico'], 'Premium': !achado['Premium'] };
      resultado[item.sku] = { achado, precisaCaminhoSecundario: precisaAlterar, todasOpcoes: opcoes };
      console.log(`  Resultado: Classico=${JSON.stringify(achado['Clássico'])} | Premium=${JSON.stringify(achado['Premium'])}`);
    }

    fs.writeFileSync(path.resolve(__dirname, 'catalogo-caminho-principal.json'), JSON.stringify(resultado, null, 2));
    console.log('\nSalvo em catalogo-caminho-principal.json');
  } catch (err) {
    console.error('ERRO GERAL:', err.message);
  } finally {
    if (browser) {
      await minimizeChrome();
      await browser.close();
    }
  }
  process.exit(0);
})();

