$excel = [Runtime.InteropServices.Marshal]::GetActiveObject('Excel.Application')
$wb = $excel.Workbooks | Where-Object { $_.Name -eq 'Analise Oficial.xlsx' }
$wsCompleto = $wb.Worksheets.Item('Mapeamento Completo da Planilha')
$wsPrioridade = $wb.Worksheets.Item('Prioridade - Fora de Ads')

foreach ($ws in @($wsCompleto, $wsPrioridade)) {
    $ws.Activate()
    $excel.ActiveWindow.DisplayGridlines = $true   # volta pro padrao

    $usedRange = $ws.UsedRange
    # AutoFit só nas linhas de dado (a partir da 2), nunca na linha 1 mesclada
    if ($usedRange.Rows.Count -ge 2) {
        $ws.Range("A2", $ws.Cells.Item($usedRange.Rows.Count, $usedRange.Columns.Count)).Rows.AutoFit() | Out-Null
    }

    # Linha 1: altura fixa manual, depois do AutoFit das outras linhas (nunca antes)
    $ws.Rows(1).RowHeight = 32
}

