    if ($a -ne '' -or $b -ne '') { Write-Output "L$r -- A: '$a' | B: '$b'" }
}

$excel = [Runtime.InteropServices.Marshal]::GetActiveObject('Excel.Application')
$wb = $excel.Workbooks | Where-Object { $_.Name -eq 'Analise Oficial.xlsx' }
$wsPrioridade = $wb.Worksheets.Item('Prioridade - Fora de Ads')

for ($r=1; $r -le 13; $r++) {
    $linha = @()
    for ($c=1; $c -le 7; $c++) {
        $l=[char](64+$c)
        $t = $wsPrioridade.Cells.Item($r,$c).Text
        if ($t -ne '') { $linha += "$l='$t'" }
    }
    if ($linha.Count -gt 0) { Write-Output "L$r : $($linha -join ' | ')" }
}

$excel = [Runtime.InteropServices.Marshal]::GetActiveObject('Excel.Application')
$wb = $excel.Workbooks | Where-Object { $_.Name -eq 'Analise Oficial.xlsx' }
$wsPrioridade = $wb.Worksheets.Item('Prioridade - Fora de Ads')

Write-Output "--- Larguras ---"
foreach ($col in @('A','B','C','D','E','F','G','H','I')) {
    Write-Output "$col : $($wsPrioridade.Columns($col).ColumnWidth)"
}
Write-Output "--- Conteudo ---"
for ($r=1; $r -le 14; $r++) {
    $a = $wsPrioridade.Cells.Item($r,1).Text
    $c = $wsPrioridade.Cells.Item($r,3).Text
    if ($a -ne '' -or $c -ne '') { Write-Output "L$r -- A: '$a' | C: '$c'" }
