const { chromium } = require('playwright');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

const URL_ADS = 'https://ads.mercadolivre.com.br/product-ads/admin/ads?navigate_to=mercado_ads';
const URL_ANUNCIOS = 'https://vendedores.mercadolivre.com.br/anuncios#menu-user';
const SELETOR_BUSCA_ADS = 'input[placeholder="Procurar por # ou título"]';
const SELETOR_BUSCA_ANUNCIOS = 'input[placeholder="Buscar por título, código ou SKU"]';
const MLB = '4484796429';
const SKU = 'TVSAM-43';

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];

    // 1) Anuncios Patrocinados -- Titulo de catalogo
    let pageAds = context.pages().find((p) => p.url().includes('ads.mercadolivre.com.br'));
    if (!pageAds) pageAds = await openBackgroundPage(browser, context, URL_ADS);
    await pageAds.waitForTimeout(1000);
    const fecharDrawer = pageAds.locator('button[aria-label="Cerrar"]');
    if (await fecharDrawer.count() > 0) { await fecharDrawer.first().click().catch(() => {}); await pageAds.waitForTimeout(400); }
    const campoAds = pageAds.locator(SELETOR_BUSCA_ADS).first();
    await campoAds.click();
    await campoAds.fill('');
    await campoAds.fill(`MLB${MLB}`);
    await pageAds.keyboard.press('Enter');
    await pageAds.waitForTimeout(2800);
    const textoAds = await pageAds.locator('body').innerText();
    const idxCat = textoAds.indexOf('CATÁLOGO');
    console.log('--- Bloco CATALOGO (Anuncios Patrocinados) ---');
    console.log(textoAds.slice(idxCat, idxCat + 300));

    // 2) Anuncios (Gestao de anuncios) -- Deposito/FULL, buscando o SKU e olhando o card desse MLB
    let pageAnuncios = context.pages().find((p) => p.url().includes('vendedores.mercadolivre.com.br/anuncios'));
    if (!pageAnuncios) pageAnuncios = await openBackgroundPage(browser, context, URL_ANUNCIOS);
    await pageAnuncios.waitForTimeout(1000);
    const campoAnuncios = pageAnuncios.locator(SELETOR_BUSCA_ANUNCIOS).first();
    await campoAnuncios.click();
    await campoAnuncios.fill('');
    await campoAnuncios.fill(SKU);
    await pageAnuncios.keyboard.press('Enter');
    await pageAnuncios.waitForTimeout(2800);
    const textoAnuncios = await pageAnuncios.locator('body').innerText();
    const idxMlb = textoAnuncios.indexOf(`#${MLB}`);
    console.log('--- Contexto ao redor do MLB na aba Anuncios (800 chars) ---');
    console.log(textoAnuncios.slice(Math.max(0, idxMlb - 300), idxMlb + 800));
  } catch (err) {
    console.error('ERRO:', err.message);
  } finally {
    if (browser) {
      await minimizeChrome();
      await browser.close();
    }
  }
  process.exit(0);
})();

