function Get-CorPorSku {
    param([string]$Sku)
    $hash = 0
    foreach ($ch in $Sku.ToCharArray()) { $hash = ($hash * 31 + [int][char]$ch) -band 0xFFFFFFF }
    $hue = $hash % 360
    $s = 0.65; $l = 0.75
    $c = (1 - [Math]::Abs(2*$l - 1)) * $s
    $x = $c * (1 - [Math]::Abs((($hue/60) % 2) - 1))
    $m = $l - $c/2
    if ($hue -lt 60) { $r=$c;$g=$x;$b=0 }
    elseif ($hue -lt 120) { $r=$x;$g=$c;$b=0 }
    elseif ($hue -lt 180) { $r=0;$g=$c;$b=$x }
    elseif ($hue -lt 240) { $r=0;$g=$x;$b=$c }
    elseif ($hue -lt 300) { $r=$x;$g=0;$b=$c }
    else { $r=$c;$g=0;$b=$x }
    $R = [Math]::Round(($r+$m)*255)
    $G = [Math]::Round(($g+$m)*255)
    $B = [Math]::Round(($b+$m)*255)
    return [int]($B*65536 + $G*256 + $R)
}

$dados = [System.IO.File]::ReadAllText("C:\Users\Felipe Augusto\projeto00\packages\karzen\.aiox-runtime\pipeline-teste-resultado.json", [System.Text.Encoding]::UTF8) | ConvertFrom-Json

$corInt = Get-CorPorSku -Sku $dados.sku
Write-Output "SKU: $($dados.sku) | Cor: $corInt"

$excel = [Runtime.InteropServices.Marshal]::GetActiveObject('Excel.Application')
$wb = $excel.Workbooks | Where-Object { $_.Name -eq 'ANÚNCIOS EM POTENCIAL - KARZEN ELETRO (1) (1).xlsx' }
$ws = $wb.Worksheets.Item('SEM CAMPANHA')

$xlValues = -4163; $xlWhole = 1
foreach ($mlb in $dados.todosMlbsSincronizados) {
    $primeira = $ws.Cells.Find($mlb, [Type]::Missing, $xlValues, $xlWhole, [Type]::Missing, [Type]::Missing, $false, [Type]::Missing, [Type]::Missing)
    if ($null -eq $primeira) { Write-Output "NAO_ACHOU: $mlb"; continue }
    $endereco = $primeira.Address()
    $atual = $primeira
    do {
        $atual.Interior.ColorIndex = -4142
        $atual.Interior.Color = $corInt
        Write-Output "Colorido $mlb -- linha $($atual.Row)"
        $atual = $ws.Cells.FindNext($atual)
    } while ($null -ne $atual -and $atual.Address() -ne $endereco)
}

