const SELETOR_BUSCA_ADS = 'input[placeholder="Procurar por # ou título"]';

const ARQUIVO_RESULTADO = path.resolve(__dirname, 'lote-completo-final.json');
const resultados = JSON.parse(fs.readFileSync(ARQUIVO_RESULTADO, 'utf8'));

const SKUS_PENDENTES = ['EMG70-220V', 'LCS15', 'HQ-264CVEFFX-127V', 'MPN-01-BF-127V', 'BBX4-JBL', 'SLKM-BIV', 'BAF45A-220V'];

async function buscarTituloComPolling(pageAds, mlb) {
  const fecharDrawer = pageAds.locator('button[aria-label="Cerrar"]');
  if (await fecharDrawer.count() > 0) { await fecharDrawer.first().click().catch(() => {}); await pageAds.waitForTimeout(300); }
  const campoAds = pageAds.locator(SELETOR_BUSCA_ADS).first();
  await campoAds.click();
  await campoAds.fill('');
  await campoAds.fill(`MLB${mlb}`);
  await pageAds.keyboard.press('Enter');

  let textoAds = '';
  let idxCat = -1;
  for (let tentativa = 0; tentativa < 6; tentativa++) {
    await pageAds.waitForTimeout(1500);
    textoAds = await pageAds.locator('body').innerText();
    idxCat = textoAds.indexOf('CATÁLOGO');
    if (idxCat !== -1) break;
  }
  if (idxCat === -1) return { titulo: null, motivo: 'CATALOGO nao apareceu apos 6 tentativas (9s)' };

  const linhasCat = textoAds.slice(idxCat, idxCat + 300).split('\n').map(l => l.trim()).filter(Boolean);
  const idxOrig = linhasCat.findIndex(l => l.includes('ORIGEM'));
  const titulo = idxOrig !== -1 ? linhasCat[idxOrig + 1] : null;
  return { titulo, motivo: titulo ? null : 'CATALOGO achado mas ORIGEM/titulo nao encontrado no slice' };
}

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    let pageAds = context.pages().find((p) => p.url().includes('ads.mercadolivre.com.br'));
    if (!pageAds) pageAds = await openBackgroundPage(browser, context, URL_ADS);
    await pageAds.waitForTimeout(1000);

    for (const sku of SKUS_PENDENTES) {
      const r = resultados[sku];
      if (!r) { console.log(`SKU ${sku} nao encontrado no JSON!`); continue; }
      const mlbTitulo = r.catalogoConfirmado['Clássico'] || r.catalogoConfirmado['Premium'];
      console.log(`\n=== ${sku} (MLB ${mlbTitulo}) ===`);
      const { titulo, motivo } = await buscarTituloComPolling(pageAds, mlbTitulo);
      if (titulo) {
        r.tituloCatalogo = titulo;
        console.log(`  OK: ${titulo}`);
      } else {
        console.log(`  FALHOU: ${motivo}`);
      }
      fs.writeFileSync(ARQUIVO_RESULTADO, JSON.stringify(resultados, null, 2));
    }

    console.log('\n\nCONCLUIDO. Resultados atualizados em lote-completo-final.json');
  } catch (err) {
    console.error('ERRO GERAL:', err.message, err.stack);
  } finally {
    if (browser) {
      await minimizeChrome();
      await browser.close();
    }
  }
  process.exit(0);
})();

