    $premium = Get-PropPremium $item.a2

    $ws.Cells.Item($linhaExcel, 1).Value2 = $item.sku
    $ws.Cells.Item($linhaExcel, 3).Value2 = Get-CelulaMlbs $item
    $ws.Cells.Item($linhaExcel, 3).WrapText = $true
