$excel = $null
try {
    $excel = [Runtime.InteropServices.Marshal]::GetActiveObject('Excel.Application')
} catch {}

if ($excel) {
    $wb = $excel.Workbooks | Where-Object { $_.Name -like '*Pausados em Campanha*' }
    if ($wb) {
        Write-Output "Ja esta aberto no Excel."
    } else {
        Write-Output "Excel esta aberto mas o arquivo 'Pausados em Campanha' nao esta entre os workbooks abertos."
        Write-Output "Abrindo agora..."
        $wb = $excel.Workbooks.Open("C:\Downloads\Pausados em Campanha - Karzen.xlsx")
    }
} else {
    Write-Output "Nenhuma instancia do Excel rodando. Abrindo uma nova..."
    $excel = New-Object -ComObject Excel.Application
    $excel.Visible = $true
    $wb = $excel.Workbooks.Open("C:\Downloads\Pausados em Campanha - Karzen.xlsx")
}

Write-Output "Abas do workbook:"
foreach ($ws in $wb.Worksheets) {
    Write-Output " - [$($ws.Name)] UsedRange: L=$($ws.UsedRange.Rows.Count) C=$($ws.UsedRange.Columns.Count)"
    $maxL = [Math]::Min(5, $ws.UsedRange.Rows.Count)
    $maxC = [Math]::Min(8, $ws.UsedRange.Columns.Count)
    for ($l = 1; $l -le $maxL; $l++) {
        $linha = @()
        for ($c = 1; $c -le $maxC; $c++) { $linha += "C$c=[$($ws.Cells.Item($l,$c).Text)]" }
        Write-Output "   L$l : $($linha -join ' | ')"
    }
}

