      console.log('\n--- Contexto Qualidade (200 antes, 400 depois) ---');
      console.log(texto.slice(Math.max(0, idxQ-200), idxQ+400));
    }
    const idxE = texto.indexOf('xperi');
    if (idxE !== -1) {
      console.log('\n--- Contexto Experiencia (200 antes, 400 depois) ---');
      console.log(texto.slice(Math.max(0, idxE-200), idxE+400));
    }
  } catch (err) {
    console.error('ERRO:', err.message, err.stack);
  } finally {
    if (browser) { await minimizeChrome(); await browser.close(); }
  }
  process.exit(0);
})();

