const { chromium } = require('playwright');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

const URL_CAMPANHA = 'https://ads.mercadolivre.com.br/product-ads/admin/campaigns/357312967/dashboard?navigate_to=mercado_ads';

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    const page = await openBackgroundPage(browser, context, URL_CAMPANHA);

    let texto = '';
    for (let t = 0; t < 8; t++) {
      await page.waitForTimeout(1500);
      texto = await page.locator('body').innerText();
      if (texto.length > 500) break;
    }
    for (let t = 0; t < 6; t++) { await page.mouse.wheel(0, 1000); await page.waitForTimeout(600); }

    const botaoPausados = page.getByText('Pausados', { exact: true }).first();
    await botaoPausados.click();
    await page.waitForTimeout(3000);
    for (let t = 0; t < 4; t++) { await page.mouse.wheel(0, 1000); await page.waitForTimeout(600); }

    // Achar o primeiro produto PAUSADO e clicar no "Ver variacoes" dele
    const primeiroPausado = page.locator('text=PAUSADO').first();
    const cardPausado = primeiroPausado.locator('xpath=ancestor::*[.//text()="Ver variações"][1]');
    // fallback: pegar o link "Ver variações" mais proximo depois do texto PAUSADO no DOM
    const linkVerVariacoes = page.locator('text=PAUSADO').first().locator('xpath=following::*[contains(text(),"Ver variações") or contains(text(),"variações")][1]');

    const countLink = await linkVerVariacoes.count();
    console.log('Link "Ver variacoes" apos o 1o PAUSADO encontrado?', countLink);

    if (countLink > 0) {
      const textoLink = await linkVerVariacoes.first().textContent();
      console.log('Texto do link:', textoLink);
      await linkVerVariacoes.first().click();
      await page.waitForTimeout(2000);

      const textoDepoisClick = await page.locator('body').innerText();
      const idxVar = textoDepoisClick.search(/\d+\s+variaç/i);
      console.log('\n--- Trecho apos clicar em Ver variacoes ---');
      console.log(textoDepoisClick.slice(Math.max(0, idxVar - 200), idxVar + 1500));
    }
  } catch (err) {
    console.error('ERRO:', err.message, err.stack);
  } finally {
    if (browser) { await minimizeChrome(); await browser.close(); }
  }
  process.exit(0);
})();

