const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

const URL_CAMPANHA = 'https://ads.mercadolivre.com.br/product-ads/admin/campaigns/357312967/dashboard?navigate_to=mercado_ads';

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    const page = await openBackgroundPage(browser, context, URL_CAMPANHA);

    let texto = '';
    for (let t = 0; t < 8; t++) {
      await page.waitForTimeout(1500);
      texto = await page.locator('body').innerText();
      if (texto.length > 500) break;
    }
    for (let t = 0; t < 6; t++) { await page.mouse.wheel(0, 1000); await page.waitForTimeout(600); }

    const botaoPausados = page.getByText('Pausados', { exact: true }).first();
    await botaoPausados.click();
    await page.waitForTimeout(3000);
    for (let t = 0; t < 4; t++) { await page.mouse.wheel(0, 1000); await page.waitForTimeout(600); }

    // Investigar a estrutura DOM: achar o elemento que contem "PAUSADO" e subir ate achar
    // um container que tambem contenha "Ver variações" -- reportar a classe desse container
    const info = await page.evaluate(() => {
      const todos = Array.from(document.querySelectorAll('*'));
      const elPausado = todos.find((el) => el.children.length === 0 && el.textContent.trim() === 'PAUSADO');
      if (!elPausado) return { erro: 'PAUSADO nao achado' };

      let atual = elPausado;
      const cadeia = [];
      for (let i = 0; i < 8 && atual; i++) {
        cadeia.push({ tag: atual.tagName, classe: atual.className, temVerVariacoes: atual.textContent.includes('Ver variações') });
        atual = atual.parentElement;
      }
      return { cadeia };
    });
    console.log(JSON.stringify(info, null, 2));
  } catch (err) {
    console.error('ERRO:', err.message, err.stack);
  } finally {
    if (browser) { await minimizeChrome(); await browser.close(); }
  }
  process.exit(0);
})();

