const { chromium } = require('playwright');
const path = require('path');
const { openBackgroundPage } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/abrir-aba-background.js'));
const { minimizeChrome } = require(path.resolve(__dirname, '../../../.aiox-core/development/scripts/modo-navegador/minimize-chrome.js'));

const URL_CAMPANHA = 'https://ads.mercadolivre.com.br/product-ads/admin/campaigns/357312967/dashboard?navigate_to=mercado_ads';

(async () => {
  let browser;
  try {
    browser = await chromium.connectOverCDP('http://localhost:9222');
    const context = browser.contexts()[0];
    const page = await openBackgroundPage(browser, context, URL_CAMPANHA);

    console.log('Aguardando pagina carregar...');
    await page.waitForTimeout(3000);
    let texto = await page.locator('body').innerText();
    for (let t = 0; t < 10 && texto.length < 500; t++) {
      await page.waitForTimeout(1500);
      texto = await page.locator('body').innerText();
    }
    console.log('Pagina carregada, tamanho:', texto.length);

    console.log('Rolando a pagina pra carregar a lista de anuncios...');
    for (let i = 0; i < 8; i++) { await page.mouse.wheel(0, 1000); await page.waitForTimeout(700); }
    await page.waitForTimeout(2000);
    texto = await page.locator('body').innerText();
    console.log('Apos rolar, tamanho:', texto.length);

    console.log('Clicando no filtro "Pausados"...');
    const botaoPausados = page.getByText('Pausados', { exact: true }).first();
    await botaoPausados.waitFor({ state: 'visible', timeout: 15000 });
    await botaoPausados.click();

    console.log('Aguardando o filtro aplicar...');
    await page.waitForTimeout(4000);
    for (let i = 0; i < 6; i++) { await page.mouse.wheel(0, 1000); await page.waitForTimeout(700); }
    await page.waitForTimeout(2000);

    texto = await page.locator('body').innerText();
    const qtdPausado = (texto.match(/PAUSADO/g) || []).length;
    console.log('Quantidade de "PAUSADO" apos filtro:', qtdPausado);

    if (qtdPausado === 0) {
      console.log('AVISO: filtro nao aplicou ainda, esperando mais um pouco e tentando de novo...');
      await page.waitForTimeout(3000);
      texto = await page.locator('body').innerText();
      console.log('Nova contagem:', (texto.match(/PAUSADO/g) || []).length);
    }

    const idxPausado = texto.indexOf('PAUSADO');
    if (idxPausado === -1) {
      console.log('Nao achei nenhum PAUSADO visivel na pagina. Parando aqui pra investigar.');
    } else {
      console.log('\n--- Contexto do 1o PAUSADO (600 chars antes) ---');
      console.log(texto.slice(Math.max(0, idxPausado - 600), idxPausado + 50));
    }
  } catch (err) {
    console.error('ERRO:', err.message, err.stack);
  } finally {
    if (browser) { await minimizeChrome(); await browser.close(); }
  }
  process.exit(0);
})();

