            r.statusCatalogoViaAlterar = { mlb: primeiroMlbSku, existeConcorrencia: false };
          }
        }
      }

      resultado[sku] = r;
    }

    fs.writeFileSync(path.resolve(__dirname, 'produto3-resultado.json'), JSON.stringify(resultado, null, 2));
    console.log('\n\nRESULTADO FINAL salvo em produto3-resultado.json');
    console.log(JSON.stringify(resultado, null, 2));
  } catch (err) {
    console.error('ERRO:', err.message, err.stack);
